class ZipManager:
    def __init__(self):
        self.zipfiles = {}
        self.added = {}

    def get_zipfile(self, name):
        cover_id = int(name[:10])
        size = name[11].lower() if name[10:11] == '-' else ''
        item, batch = Cover.id_to_item_and_batch_id(cover_id)
        path = Batch.get_abspath(item, batch, size)
        if path not in self.zipfiles:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            archive = zipfile.ZipFile(path, 'a', compression=zipfile.ZIP_STORED,
                                      allowZip64=True)
            self.zipfiles[path] = archive
            self.added[path] = set(archive.namelist())
        return self.zipfiles[path], path

    def add_file(self, name, filepath, mtime):
        archive, path = self.get_zipfile(name)
        if name not in self.added[path]:
            date = time.localtime(mtime)[:6]
            info = zipfile.ZipInfo(name, date_time=date)
            info.compress_type = zipfile.ZIP_STORED
            with open(filepath, 'rb') as source:
                archive.writestr(info, source.read())
            self.added[path].add(name)
        return f'{os.path.relpath(path, config.data_root)}/{name}'

    def close(self):
        for archive in self.zipfiles.values():
