@contextmanager
def _batch_lock(item, batch):
    \"\"\"Serialize staging and finalization of a batch across local processes.\"\"\"
    import fcntl
    lockdir = os.path.join(config.data_root, 'items', '.locks')
    os.makedirs(lockdir, exist_ok=True)
    with open(os.path.join(lockdir, f'{item}_{batch}.lock'), 'w') as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)
        try:
            yield
        finally:
            fcntl.flock(lock, fcntl.LOCK_UN)


class ZipManager:
    def __init__(self):
        self.zipfiles = {}
        self.added = {}

    def get_zipfile(self, name):
        cover_id = int(name[:10])
        size = name[11].lower() if name[10:11] == '-' else ''
        item, batch = Cover.id_to_item_and_batch_id(cover_id)
        path = Batch.get_abspath(item, batch, size)
        if path not in self.zipfiles:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            archive = zipfile.ZipFile(path, 'a', compression=zipfile.ZIP_STORED,
                                      allowZip64=True)
            self.zipfiles[path] = archive
            self.added[path] = set(archive.namelist())
        return self.zipfiles[path], path

    def add_file(self, name, filepath, mtime):
        archive, path = self.get_zipfile(name)
        if name not in self.added[path]:
            date = time.localtime(mtime)[:6]
            info = zipfile.ZipInfo(name, date_time=date)
            info.compress_type = zipfile.ZIP_STORED
            with open(filepath, 'rb') as source:
                archive.writestr(info, source.read())
            self.added[path].add(name)
        return f'{os.path.relpath(path, config.data_root)}/{name}'

    def close(self):
        for archive in self.zipfiles.values():
            archive.close()
        self.zipfiles.clear()


def open_zipfile(name):
    manager = ZipManager()
    archive, _ = manager.get_zipfile(name)
    return archive


def get_zipfile(name):
    return open_zipfile(name)


def count_files_in_zip(filepath):
    with zipfile.ZipFile(filepath) as archive:
        return sum(name.lower().endswith('.jpg') for name in archive.namelist())


class Uploader:
    def upload(self, itemname, filepaths):
        return subprocess.run(['ia', 'upload', itemname, *filepaths, '--retries', '10'],
                              check=True, capture_output=True, text=True)

    @staticmethod
    def is_uploaded(item, zip_filename, verbose=False):
        result = subprocess.run(['ia', 'list', item], check=True, capture_output=True,
                                text=True)
        return zip_filename in result.stdout.splitlines()


